import 'package:dio/dio.dart';import 'package:flutter/foundation.dart';import 'package:gamezone/core/networking/api_constants.dart';import 'package:pretty_dio_logger/pretty_dio_logger.dart';class DioFactory {  static Dio? _authDio;  static Dio? _gameDio;  static Dio getAuthDio() {    if (_authDio != null) {      return _authDio!;    }    _authDio = Dio(      BaseOptions(        baseUrl: ApiConstants.dummyJsonBaseUrl,        receiveTimeout: const Duration(seconds: 30),        connectTimeout: const Duration(seconds: 30),        sendTimeout: const Duration(seconds: 30),        headers: {          'Accept': 'application/json',          'Content-Type': 'application/json',        },      ),    );    _addLogger(_authDio!);    return _authDio!;  }  static Dio getGameDio() {    if (_gameDio != null) {      return _gameDio!;    }    _gameDio = Dio(      BaseOptions(        baseUrl: ApiConstants.rawgBaseUrl,        receiveTimeout: const Duration(seconds: 30),        connectTimeout: const Duration(seconds: 30),        sendTimeout: const Duration(seconds: 30),        headers: {          'Accept': 'application/json',          'Content-Type': 'application/json',        },      ),    );    _addLogger(_gameDio!);    return _gameDio!;  }  static void _addLogger(Dio dio) {    dio.interceptors.add(      PrettyDioLogger(        requestHeader: true,        requestBody: true,        responseBody: true,        responseHeader: false,        error: true,        compact: true,        maxWidth: 90,        enabled: kDebugMode,      ),    );  }}